import { useState, useEffect } from 'react'
import userService from '../../services/userService'

const ROLES = ['Admin', 'Staf', 'AVP & VP']

const emptyForm = {
  username: '',
  firstName: '',
  lastName: '',
  password: '',
  role: 'Staf'
}

const UserManagementPage = () => {
  const [users, setUsers] = useState([])
  const [loading, setLoading] = useState(true)
  const [showModal, setShowModal] = useState(false)
  const [editUser, setEditUser] = useState(null)
  const [form, setForm] = useState(emptyForm)
  const [error, setError] = useState('')
  const [submitLoading, setSubmitLoading] = useState(false)

  const fetchUsers = async () => {
    try {
      const res = await userService.getAllUsers()
      setUsers(res.data)
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchUsers()
  }, [])

  const openAddModal = () => {
    setEditUser(null)
    setForm(emptyForm)
    setError('')
    setShowModal(true)
  }

  const openEditModal = (user) => {
    setEditUser(user)
    setForm({
      username: user.username,
      firstName: user.firstName,
      lastName: user.lastName,
      password: '',
      role: user.role
    })
    setError('')
    setShowModal(true)
  }

  const closeModal = () => {
    setShowModal(false)
    setEditUser(null)
    setForm(emptyForm)
    setError('')
  }

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value })
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    setError('')
    setSubmitLoading(true)

    try {
      if (editUser) {
        const updateData = {
          firstName: form.firstName,
          lastName: form.lastName,
          role: form.role
        }
        if (form.password) updateData.password = form.password
        await userService.updateUser(editUser.id, updateData)
      } else {
        await userService.createUser(form)
      }
      await fetchUsers()
      closeModal()
    } catch (err) {
      setError(err.response?.data?.message || 'Terjadi kesalahan')
    } finally {
      setSubmitLoading(false)
    }
  }

  const handleToggleStatus = async (user) => {
    try {
      await userService.updateUserStatus(user.id, !user.isActive)
      await fetchUsers()
    } catch (err) {
      alert(err.response?.data?.message || 'Terjadi kesalahan')
    }
  }

  return (
    <div style={styles.container}>
      {/* Header */}
      <div style={styles.header}>
        <div>
          <h1 style={styles.title}>User Management</h1>
        </div>
        <button onClick={openAddModal} style={styles.addButton}>
          + Add New User
        </button>
      </div>

      {/* Table */}
      <div style={styles.tableWrapper}>
        {loading ? (
          <p style={styles.loadingText}>Memuat data...</p>
        ) : (
          <table style={styles.table}>
            <thead>
              <tr style={styles.tableHead}>
                <th style={styles.th}>No</th>
                <th style={styles.th}>Username</th>
                <th style={styles.th}>Nama Lengkap</th>
                <th style={styles.th}>Peran</th>
                <th style={styles.th}>Status</th>
                <th style={styles.th}>Aksi</th>
              </tr>
            </thead>
            <tbody>
              {users.map((user, index) => (
                <tr key={user.id} style={styles.tableRow}>
                  <td style={styles.td}>{index + 1}</td>
                  <td style={styles.td}>{user.username}</td>
                  <td style={styles.td}>{user.firstName} {user.lastName}</td>
                  <td style={styles.td}>
                    <span style={{
                      ...styles.roleBadge,
                      backgroundColor: user.role === 'Admin' ? '#fce4ec' : user.role === 'Staf' ? '#e3f2fd' : '#f3e5f5',
                      color: user.role === 'Admin' ? '#c2185b' : user.role === 'Staf' ? '#1565c0' : '#6a1b9a'
                    }}>
                      {user.role}
                    </span>
                  </td>
                  <td style={styles.td}>
                    <span style={{
                      ...styles.statusBadge,
                      backgroundColor: user.isActive ? '#e8f5e9' : '#fafafa',
                      color: user.isActive ? '#2e7d32' : '#999'
                    }}>
                      {user.isActive ? 'Aktif' : 'Nonaktif'}
                    </span>
                  </td>
                  <td style={styles.td}>
                    <div style={styles.actionButtons}>
                      <button
                        onClick={() => openEditModal(user)}
                        style={styles.editButton}
                      >
                        Edit
                      </button>
                      <button
                        onClick={() => handleToggleStatus(user)}
                        style={{
                          ...styles.toggleButton,
                          backgroundColor: user.isActive ? '#fff3e0' : '#e8f5e9',
                          color: user.isActive ? '#e65100' : '#2e7d32'
                        }}
                      >
                        {user.isActive ? 'Nonaktifkan' : 'Aktifkan'}
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* Modal */}
      {showModal && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}>
            <div style={styles.modalHeader}>
              <h2 style={styles.modalTitle}>
                {editUser ? 'Edit Pengguna' : 'Tambah Pengguna Baru'}
              </h2>
              <button onClick={closeModal} style={styles.closeButton}>✕</button>
            </div>

            <form onSubmit={handleSubmit} style={styles.form}>
              {!editUser && (
                <div style={styles.formGroup}>
                  <label style={styles.label}>Username</label>
                  <input
                    name="username"
                    value={form.username}
                    onChange={handleChange}
                    style={styles.input}
                    placeholder="Masukkan username"
                    required
                  />
                </div>
              )}

              <div style={styles.formRow}>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Nama Depan</label>
                  <input
                    name="firstName"
                    value={form.firstName}
                    onChange={handleChange}
                    style={styles.input}
                    placeholder="Nama depan"
                    required
                  />
                </div>
                <div style={styles.formGroup}>
                  <label style={styles.label}>Nama Belakang</label>
                  <input
                    name="lastName"
                    value={form.lastName}
                    onChange={handleChange}
                    style={styles.input}
                    placeholder="Nama belakang"
                    required
                  />
                </div>
              </div>

              <div style={styles.formGroup}>
                <label style={styles.label}>
                  Password {editUser && <span style={styles.optional}>(kosongkan jika tidak diubah)</span>}
                </label>
                <input
                  name="password"
                  type="password"
                  value={form.password}
                  onChange={handleChange}
                  style={styles.input}
                  placeholder={editUser ? 'Password baru (opsional)' : 'Masukkan password'}
                  required={!editUser}
                />
              </div>

              <div style={styles.formGroup}>
                <label style={styles.label}>Peran</label>
                <select
                  name="role"
                  value={form.role}
                  onChange={handleChange}
                  style={styles.input}
                  required
                >
                  {ROLES.map(role => (
                    <option key={role} value={role}>{role}</option>
                  ))}
                </select>
              </div>

              {error && <p style={styles.error}>{error}</p>}

              <div style={styles.modalFooter}>
                <button type="button" onClick={closeModal} style={styles.cancelButton}>
                  Batal
                </button>
                <button
                  type="submit"
                  style={{ ...styles.submitButton, opacity: submitLoading ? 0.7 : 1 }}
                  disabled={submitLoading}
                >
                  {submitLoading ? 'Menyimpan...' : editUser ? 'Simpan Perubahan' : 'Tambah Pengguna'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

